399|    const docTitle = titleEl === undefined ? null : clean(titleEl.textContent) || null;
400|    sections.push({
401|      id: name,
402|      href: manifestItem.href,
403|      linear: ref.linear,
404|      types: [...new Set(types)],
405|      docTitle,
406|      navLabel: labels.get(manifestItem.href) ?? null,
407|      blocks: spineBlocks(doc),
