11|export const DAILY_SPEND_TTL_SEC = 48 * 3600;
12|
13|export function dailySpendKey(day: string): string {
14|  return `img:spend:daily:${day}`;
15|}
16|
17|export function budgetExceeded(totalAfterReserve: number, capMicro: number): boolean {
18|  return totalAfterReserve > capMicro;
19|}
20|
21|export interface SpendReservation {
22|  amountMicro: number;
23|  day: string;
24|  // Gives back each counter at most once: a flag clears only after
25|  // its write lands. Best effort, never throws.
26|  release(): Promise<void>;
27|  // Post-stream reconciliation: folds the real cost into both counters.
28|  // Best effort, never throws.
29|  adjust(deltaMicro: number): Promise<void>;
30|}
31|
32|export interface ReserveSpendArgs {
33|  amountMicro: number;
34|  day: string;
35|  spendCapMicro: number;
36|  dailySpendCapMicro: number;
37|}
38|
39|// One reserve for both caps: total first with an expiry refresh on the
40|// daily counter, refunding what was taken on over-cap. A Redis failure
41|// between reserves refunds the total, then rethrows for the caller to
42|// map to unavailable. Only over-cap returns ok: false.
43|export async function reserveSpend(
44|  kv: KV,
45|  args: ReserveSpendArgs,
46|): Promise<{ ok: true; reservation: SpendReservation } | { ok: false; which: "total" | "daily" }> {
47|  const totalKey = spendKey();
48|  const dayKey = dailySpendKey(args.day);
49|  let totalLeft = false;
50|  let dailyLeft = false;
51|  const releaseTotal = async (): Promise<void> => {
52|    try {
53|      if (totalLeft) {
54|        await kv.decrBy(totalKey, args.amountMicro);
55|        totalLeft = false;
56|      }
57|    } catch {
58|      // Redis down: nothing reserved server-side to retry against.
59|    }
60|  };
61|  const releaseDaily = async (): Promise<void> => {
62|    try {
63|      if (dailyLeft) {
64|        await kv.decrBy(dayKey, args.amountMicro);
65|        dailyLeft = false;
66|      }
67|    } catch {
68|      // Redis down: nothing reserved server-side to retry against.
69|    }
70|  };
71|
72|  const total = await kv.incrBy(totalKey, args.amountMicro);
73|  totalLeft = true;
74|  if (budgetExceeded(total, args.spendCapMicro)) {
75|    await releaseTotal();
76|    return { ok: false, which: "total" };
77|  }
78|
79|  let dailyTotal: number;
80|  try {
81|    dailyTotal = await kv.incrBy(dayKey, args.amountMicro);
82|    dailyLeft = true;
83|    await kv.expire(dayKey, DAILY_SPEND_TTL_SEC);
84|  } catch (e) {
85|    // A Redis failure between reserves must give back what was taken.
86|    await releaseDaily();
87|    await releaseTotal();
88|    throw e;
89|  }
90|  if (budgetExceeded(dailyTotal, args.dailySpendCapMicro)) {
91|    await releaseDaily();
92|    await releaseTotal();
93|    return { ok: false, which: "daily" };
94|  }
95|
96|  // Refunds the day that was charged, even if the job crosses UTC midnight.
97|  return {
98|    ok: true,
99|    reservation: {
100|      amountMicro: args.amountMicro,
101|      day: args.day,
102|      release: async () => {
103|        await releaseDaily();
104|        await releaseTotal();
105|      },
106|      adjust: async (deltaMicro: number) => {
107|        if (deltaMicro === 0) return;
108|        try {
109|          await kv.incrBy(totalKey, deltaMicro);
110|          await kv.incrBy(dayKey, deltaMicro);
111|        } catch {
112|          // Best effort: the reserve already bounds the spend.
113|        }
114|      },
115|    },
116|  };
