Read text file `pipeline/meta.ts`.
1|// Meta chat client (OpenAI compatible body, json_schema output).
2|// Never logs headers or keys; errors carry status plus a short excerpt.
3|import { fetchWithRetry, retryableError } from "./http";
4|import type { CleanProvider } from "../core/clean-types";
5|
6|export interface MetaUsage {
7|  data: unknown;
8|  promptTokens: number;
9|  cachedTokens: number;
10|  completionTokens: number;
11|}
12|
13|export interface MetaClient {
14|  model: string;
15|  provider?: CleanProvider;
16|  completeJson(input: {
17|    system: string;
18|    user: string;
19|    schemaName: string;
20|    schema: Record<string, unknown>;
21|  }): Promise<MetaUsage>;
22|}
23|
24|const META_URL = "https://api.meta.ai/v1/chat/completions";
25|
26|export function createMetaClient(input: {
27|  fetchFn?: typeof fetch;
28|  apiKey: string;
29|  model: string;
30|  url?: string;
31|  provider?: CleanProvider;
32|}): MetaClient {
33|  const fetchFn = input.fetchFn ?? fetch;
34|  const provider = input.provider ?? "meta";
35|  const label = provider === "modal" ? "Modal" : "Meta";
36|  return {
37|    model: input.model,
38|    provider,
39|    completeJson: async ({ system, user, schemaName, schema }) => {
40|      const body = JSON.stringify({
41|        model: input.model,
42|        messages: [
43|          { role: "system", content: system },
44|          { role: "user", content: user },
45|        ],
46|        reasoning_effort: "low",
47|        max_tokens: 4000,
48|        response_format: { type: "json_schema", json_schema: { name: schemaName, strict: true, schema } },
49|      });
50|      // fetchWithRetry owns network/429/5xx retries. Small max_tokens
51|      // can return empty content, so that gets one extra attempt here.
52|      let lastError: unknown = null;
53|      for (let attempt = 1; attempt <= 2; attempt++) {
54|        const response = await fetchWithRetry(
55|          fetchFn,
56|          input.url ?? META_URL,
57|          {
58|            method: "POST",
59|            headers: { Authorization: `Bearer ${input.apiKey}`, "Content-Type": "application/json" },
60|            body,
61|          },
62|          { attempts: 3 },
63|        );
64|        const parsed = (await response.json()) as {
65|          choices?: { message?: { content?: string | null } }[];
66|          usage?: { prompt_tokens?: number; prompt_tokens_details?: { cached_tokens?: number }; completion_tokens?: number };
67|        };
68|        const content = parsed.choices?.[0]?.message?.content;
69|        if (typeof content === "string" && content.trim().length > 0) {
70|          try {
71|            return {
72|              data: JSON.parse(content) as unknown,
73|              promptTokens: parsed.usage?.prompt_tokens ?? 0,
74|              cachedTokens: parsed.usage?.prompt_tokens_details?.cached_tokens ?? 0,
75|              completionTokens: parsed.usage?.completion_tokens ?? 0,
76|            };
77|          } catch {
78|            lastError = retryableError(`${label} returned unparseable JSON content`);
79|          }
80|        } else {
81|          lastError = retryableError(`${label} returned empty content`);
82|        }
83|      }
84|      throw lastError instanceof Error ? lastError : new Error(String(lastError));
85|    },
86|  };
87|}

