1|// Step 1: ingest the raw Gutenberg text into data/books/<key>/book.json.
2|// Frozen: a textVersion drift fails unless --force; a match leaves the
3|// file untouched.
4|import { createHash } from "node:crypto";
5|import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
6|import { join } from "node:path";
7|import { JSDOM } from "jsdom";
8|import { cleanSections } from "../core/clean";
9|import type { Judge } from "../core/clean";
10|import { readEpubSections } from "../core/epub";
11|import { buildBook, canonicalLines, splitChapters, stripGutenberg } from "../core/gutenberg";
12|import type { Book } from "../core/types";
13|import books from "./books.json" with { type: "json" };
14|
15|export interface StepCtx {
16|  bookKey: string;
17|  force: boolean;
18|  dir: string;
19|}
20|
21|export interface BookConfig {
22|  gutenberg: number;
23|  title: string;
24|  author: string;
25|  format?: string;
26|}
27|
28|export function bookConfig(bookKey: string): BookConfig {
29|  const config = (books as Record<string, BookConfig>)[bookKey];
30|  if (!config) throw new Error(`unknown book "${bookKey}", valid keys: ${Object.keys(books).join(", ")}`);
31|  return config;
32|}
33|
34|export function textVersionFor(book: Omit<Book, "textVersion">): string {
35|  return `sha256:${createHash("sha256").update(canonicalLines(book.paragraphs)).digest("hex")}`;
36|}
37|
38|async function loadRaw(bookKey: string, gutenberg: number, fetchFn: typeof fetch): Promise<string> {
39|  const local = join("data", "raw", bookKey, `pg${gutenberg}.txt`);
40|  if (existsSync(local)) return readFileSync(local, "utf8");
41|  const url = `https://www.gutenberg.org/cache/epub/${gutenberg}/pg${gutenberg}.txt`;
42|  const response = await fetchFn(url);
43|  if (!response.ok) throw new Error(`download failed with status ${response.status}`);
44|  return await response.text();
45|}
46|
47|async function loadEpub(
48|  bookKey: string,
49|  gutenberg: number,
50|  fetchFn: typeof fetch,
51|): Promise<Uint8Array> {
52|  const local = join("data", "raw", bookKey, `pg${gutenberg}.epub`);
53|  if (existsSync(local)) return new Uint8Array(readFileSync(local));
54|  const url = `https://www.gutenberg.org/cache/epub/${gutenberg}/pg${gutenberg}-images-3.epub`;
55|  const response = await fetchFn(url);
56|  if (!response.ok) throw new Error(`download failed with status ${response.status}`);
57|  return new Uint8Array(await response.arrayBuffer());
58|}
59|
60|export async function runIngest(
61|  ctx: StepCtx,
62|  deps?: { fetchFn?: typeof fetch; judge?: Judge; config?: BookConfig },
63|): Promise<Book> {
64|  const config = deps?.config ?? bookConfig(ctx.bookKey);
65|  if (config.format === "epub") {
66|    const bytes = await loadEpub(ctx.bookKey, config.gutenberg, deps?.fetchFn ?? fetch);
67|    const { title, sections } = readEpubSections(bytes, (text, type) => {
68|      if (type === "text/html") return new JSDOM(text).window.document;
69|      return new JSDOM(text, { contentType: type }).window.document;
70|    });
71|    void title;
72|    const cleaned = await cleanSections(config.title, sections, deps?.judge);
73|    if (cleaned.chapters.length === 0) throw new Error("no chapters found after cleaning");
74|    const drafts = cleaned.chapters.map((c) => ({ title: c.title, paragraphs: c.paragraphs }));
75|    return writeBook(
76|      ctx,
77|      { title: config.title, author: config.author, gutenberg: config.gutenberg, chapters: drafts },
78|      () => {
79|        mkdirSync(ctx.dir, { recursive: true });
80|        writeFileSync(join(ctx.dir, "clean-report.json"), `${JSON.stringify(cleaned.report)}\n`);
81|      },
82|    );
83|  }
84|  const raw = await loadRaw(ctx.bookKey, config.gutenberg, deps?.fetchFn ?? fetch);
85|  const drafts = splitChapters(stripGutenberg(raw));
86|  if (drafts.length === 0) throw new Error("no chapters found after ingest");
87|  return writeBook(ctx, { title: config.title, author: config.author, gutenberg: config.gutenberg, chapters: drafts });
88|}
89|
90|function writeBook(
91|  ctx: StepCtx,
92|  input: { title: string; author: string; gutenberg: number; chapters: { title: string; paragraphs: string[] }[] },
93|  afterDriftCheck?: () => void,
94|): Book {
95|  const book = { ...buildBook({ id: ctx.bookKey, ...input }), textVersion: "" };
96|  book.textVersion = textVersionFor(book);
97|  mkdirSync(ctx.dir, { recursive: true });
98|  const path = join(ctx.dir, "book.json");
99|  if (existsSync(path)) {
100|    const existing = JSON.parse(readFileSync(path, "utf8")) as Book;
101|    if (existing.textVersion === book.textVersion) return existing;
102|    if (!ctx.force) {
103|      throw new Error(`textVersion drift for ${ctx.bookKey} (rerun with --force to overwrite)`);
104|    }
105|  }
106|  afterDriftCheck?.();
107|  writeFileSync(path, `${JSON.stringify(book)}\n`);
108|  return book;
109|}

