1|// Step 4: cluster classified scenes into about 15 track prompts.
2|// No network in this step and no audio code anywhere.
3|import { readFileSync, writeFileSync } from "node:fs";
4|import { join } from "node:path";
5|import { buildFeatures, dominantIndex, kmeans } from "../core/cluster";
6|import type { WeightedPoint } from "../core/cluster";
7|import { bpmRange, buildTrackPrompt } from "../core/music-prompt";
8|import { EMOTIONS, FEATURE_WEIGHTS } from "../core/types";
9|import type { AnalyzedScene, Book, EmotionId } from "../core/types";
10|import { clusterKeys, decide } from "./freshness";
11|import type { StepCtx } from "./ingest";
12|
13|const SEED = 42;
14|
15|export async function runCluster(ctx: StepCtx): Promise<void> {
16|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
17|  const analysis = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
18|    scenes: AnalyzedScene[];
19|  };
20|  const outPath = join(ctx.dir, "music-clusters.json");
21|  const keys = clusterKeys(ctx.dir);
22|  if (decide(ctx.force, keys.recorded, keys.current).reuse) return;
23|  const classified = analysis.scenes.filter((s): s is AnalyzedScene & { final: NonNullable<AnalyzedScene["final"]> } => s.final !== null);
24|  const byId = new Map(classified.map((s) => [s.id, s]));
25|  const unclustered = analysis.scenes.filter((s) => s.final === null).map((s) => s.id);
26|  const points: WeightedPoint[] = classified.map((s) => ({
27|    sceneId: s.id,
28|    features: buildFeatures({ vector: s.final.vector, intensity: s.final.intensity, tempo: s.final.tempo }),
29|  }));
30|  const k = Math.min(15, points.length);
31|  const clusters = kmeans(points, k, { seed: SEED, restarts: 20, maxIter: 100 })
32|    .map((cluster) => {
33|      const intensity = Math.min(1, Math.max(0, (cluster.centroid[8] ?? 0) / FEATURE_WEIGHTS.intensity));
34|      const tempo = Math.min(1, Math.max(0, (cluster.centroid[9] ?? 0) / FEATURE_WEIGHTS.tempo));
35|      return { cluster, intensity, tempo, dominant: dominantIndex(cluster.centroid) };
36|    })
37|    .sort((a, b) => a.dominant - b.dominant || a.intensity - b.intensity)
38|    .map(({ cluster, intensity, tempo }, index) => {
39|      const vector = Object.fromEntries(EMOTIONS.map((id, i) => [id, cluster.centroid[i] ?? 0]));
40|      const ranked = (Object.entries(vector) as [EmotionId, number][]).sort((a, b) => b[1] - a[1]);
41|      const scenes = cluster.points
42|        .map((p) => byId.get(p.sceneId))
43|        .filter((s) => s !== undefined)
44|        .sort((a, b) => a.start_n - b.start_n)
45|        .map((s) => s.id);
46|      return {
47|        id: `t${String(index + 1).padStart(2, "0")}`,
48|        size: cluster.points.length,
49|        centroid: { vector, intensity, tempo },
50|        dominant: ranked.slice(0, 2).map(([id]) => id),
51|        bpm: bpmRange(tempo),
52|        scenes,
53|        prompt: buildTrackPrompt({ top: ranked.slice(0, 3).map(([id, weight]) => ({ id, weight })), intensity, tempo }),
54|      };
55|    });
56|  writeFileSync(
57|    outPath,
58|    `${JSON.stringify({ bookId: book.id, textVersion: book.textVersion, k, seed: SEED, feature_weights: FEATURE_WEIGHTS, clusters, unclustered, provenance: { date: new Date().toISOString(), input: keys.current } })}\n`,
59|  );
60|}

