127|      for (let n = parsed.n; n <= (parsed.endN ?? parsed.n); n++) passageTexts.push(byN.get(n) ?? "");
128|    }
129|    const sceneParas = sceneOf
130|      ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
131|      : [];
132|    // Chapter content comes from the frozen book: the chapter title plus
133|    // the panel groups over that chapter's scenes. The client sends the
134|    // chapter number only, so no client text reaches the prompt.
135|    const chapterNo = parsed.kind === "chapter" ? parsed.ch : null;
136|    const content: ImageContent =
137|      chapterNo !== null
