160|    const humanOut: { setCookie?: string } = {};
161|    const res = await orchestrate(parsed, {
162|      kv: deps.kv ?? createRestKV(env.upstashUrl, env.upstashToken),
163|      store: deps.store ?? createBlobStore(),
164|      generate: deps.generate ?? createMetaClient(env.metaKey),
165|      env,
