177|        turnstileSiteKey: env.turnstileSiteKey,
178|        sessionSecret: env.sessionSecret,
179|        fetchFn: deps.fetchFn,
180|      },
181|      humanOut,
182|    });
183|
184|    const { json, status } = toResponse(res);
185|    const headers = new Headers();
186|    if (setCookie) headers.append("Set-Cookie", setCookie);
187|    if (humanOut.setCookie) headers.append("Set-Cookie", humanOut.setCookie);
