125|    const passageTexts: string[] = [];
126|    if (parsed.kind === "passage") {
127|      for (let n = parsed.n; n <= (parsed.endN ?? parsed.n); n++) passageTexts.push(byN.get(n) ?? "");
128|    }
129|    const sceneParas = sceneOf
130|      ? book.paragraphs.filter((p) => p.n >= sceneOf.start_n && p.n <= sceneOf.end_n)
131|      : [];
132|    // Chapter content comes from the frozen book: the chapter title plus
133|    // the panel groups over that chapter's scenes. The client sends the
134|    // chapter number only, so no client text reaches the prompt.
135|    const chapterNo = parsed.kind === "chapter" ? parsed.ch : null;
136|    const content: ImageContent =
137|      chapterNo !== null
138|        ? {
139|            passageText: "",
140|            sceneTitle: book.chapters.find((c) => c.ch === chapterNo)?.title ?? "",
141|            sceneClip: "",
142|            chapterPanels: chapterPanels(scenes.filter((s) => s.ch === chapterNo)),
143|          }
144|        : {
145|            passageText: parsed.kind === "passage" ? passageTexts.join(" ") : "",
146|            sceneTitle: sceneOf?.title ?? "",
147|            sceneClip: sceneParas.map((p) => p.text).join(" "),
148|          };
149|
150|    const cookieValue = parseAnonCookie(req.headers.get("cookie"));
151|    let anonId = cookieValue ? verifyAnonCookie(cookieValue, env.sessionSecret) : null;
152|    let setCookie: string | null = null;
153|    if (!anonId) {
154|      const issued = issueAnonId(env.sessionSecret);
155|      anonId = issued.id;
156|      setCookie = serializeAnonCookie(issued.value);
157|    }
158|
159|    const ip = clientIp(req.headers);
160|    const humanOut: { setCookie?: string } = {};
161|    const res = await orchestrate(parsed, {
162|      kv: deps.kv ?? createRestKV(env.upstashUrl, env.upstashToken),
163|      store: deps.store ?? createBlobStore(),
164|      generate: deps.generate ?? createMetaClient(env.metaKey),
165|      env,
166|      content,
167|      ip,
168|      anonId,
169|      day: utcDay(),
170|      sceneId: sceneOf?.id ?? "",
171|      // On the miss path only; cache hits return before this is read.
172|      human: {
173|        cookieHeader: req.headers.get("cookie"),
174|        token: parsed.turnstileToken,
175|        ip,
176|        turnstileSecret: env.turnstileSecret,
177|        turnstileSiteKey: env.turnstileSiteKey,
178|        sessionSecret: env.sessionSecret,
179|        fetchFn: deps.fetchFn,
180|      },
181|      humanOut,
182|    });
183|
184|    const { json, status } = toResponse(res);
185|    const headers = new Headers();
186|    if (setCookie) headers.append("Set-Cookie", setCookie);
187|    if (humanOut.setCookie) headers.append("Set-Cookie", humanOut.setCookie);
