5|// Reads image env once per request. Any missing key means unavailable:
6|// with no quotas or budget configured, the route must never spend.
7|export interface ImageEnv extends TurnstilePair {
8|  upstashUrl: string;
9|  upstashToken: string;
10|  metaKey: string;
11|  sessionSecret: string;
12|  ipSalt: string;
