15|}
16|
17|// Vercel's Upstash marketplace integration injects KV_REST_API_* names.
18|// UPSTASH_* wins when non-empty, else the KV_* fallback applies per value.
19|// The read-only token is never used (we write).
20|const URL_NAMES = "UPSTASH_REDIS_REST_URL|KV_REST_API_URL";
21|const TOKEN_NAMES = "UPSTASH_REDIS_REST_TOKEN|KV_REST_API_TOKEN";
22|
23|const REQUIRED = [
24|  "BLOB_READ_WRITE_TOKEN",
25|  "META_API_KEY",
26|  "SESSION_SECRET",
27|  "IP_HASH_SALT",
28|] as const;
29|
30|export function readImageEnv(from: NodeJS.ProcessEnv = process.env): ImageEnv {
31|  const upstashUrl = usable(from.UPSTASH_REDIS_REST_URL) ?? usable(from.KV_REST_API_URL);
32|  const upstashToken = usable(from.UPSTASH_REDIS_REST_TOKEN) ?? usable(from.KV_REST_API_TOKEN);
33|  // A non-https URL is a placeholder or typo, never a real endpoint.
34|  const url = upstashUrl?.startsWith("https://") ? upstashUrl : undefined;
35|  const missing = [
36|    url ? null : URL_NAMES,
37|    upstashToken ? null : TOKEN_NAMES,
38|    ...REQUIRED.filter((k) => !usable(from[k])),
39|  ].filter((m): m is string => m !== null);
40|  if (missing.length > 0) throw new Error(`missing image env: ${missing.join(",")}`);
41|  return {
42|    upstashUrl: url as string,
43|    upstashToken: upstashToken as string,
44|    metaKey: from.META_API_KEY as string,
45|    sessionSecret: from.SESSION_SECRET as string,
