76|export class ChatValidationError extends Error {
77|  constructor(message = "invalid chat request") {
78|    super(message);
79|    this.name = "ChatValidationError";
80|  }
81|}
82|
83|function isRecord(json: unknown): json is Record<string, unknown> {
84|  return typeof json === "object" && json !== null && !Array.isArray(json);
85|}
86|
87|// Strict parse at the trust boundary: only known fields are kept, so a
88|// client bug cannot widen the context or spend budget on a misread request.
89|export function parseChatRequest(json: unknown): ChatRequest {
90|  if (!isRecord(json)) throw new ChatValidationError();
91|  if (json.bookId !== "oz") throw new ChatValidationError();
92|  const upToN = json.upToN;
93|  if (typeof upToN !== "number" || !Number.isSafeInteger(upToN) || upToN <= 0) {
94|    throw new ChatValidationError();
95|  }
96|  if (typeof json.spoilers !== "boolean") throw new ChatValidationError();
97|  const rawMessages = json.messages;
98|  if (!Array.isArray(rawMessages) || rawMessages.length < 1 || rawMessages.length > CHAT_MAX_MESSAGES + 1) {
99|    throw new ChatValidationError();
100|  }
101|  const messages: ChatMessage[] = rawMessages.map((item, index) => {
102|    if (!isRecord(item)) throw new ChatValidationError();
103|    if (item.role !== "user" && item.role !== "assistant") throw new ChatValidationError();
104|    if (typeof item.content !== "string" || item.content.length === 0) {
105|      throw new ChatValidationError();
106|    }
107|    const last = index === rawMessages.length - 1;
108|    if (item.role === "user") {
109|      if (item.content.trim().length === 0 || item.content.trim().length > CHAT_MAX_QUESTION_CHARS) {
110|        throw new ChatValidationError();
111|      }
112|    } else if (item.content.length > CHAT_MAX_ANSWER_CHARS) {
113|      throw new ChatValidationError();
114|    }
115|    if (last && item.role !== "user") throw new ChatValidationError();
116|    return { role: item.role, content: item.content };
117|  });
118|  const out: ChatRequest = {
119|    bookId: "oz",
120|    upToN,
121|    spoilers: json.spoilers,
122|    messages,
123|  };
124|  if (json.turnstileToken !== undefined) {
125|    if (typeof json.turnstileToken !== "string" || json.turnstileToken.length > 2048) {
126|      throw new ChatValidationError();
127|    }
128|    out.turnstileToken = json.turnstileToken;
129|  }
130|  return out;
