177|export function buildChatSystemPrompt(args: {
178|  title: string;
179|  author: string;
180|  chapterNumber: number;
181|  chapterTitle: string;
182|  spoilers: boolean;
183|  bookText: string;
184|}): string {
185|  const scope = args.spoilers
186|    ? "The reader may ask about the whole book."
187|    : `The reader has read up to Chapter ${args.chapterNumber}, "${args.chapterTitle}". ` +
188|      "Never mention or hint at anything after this point, even if you know the book.";
189|  return (
190|    `Book text of "${args.title}" by ${args.author}:\n${args.bookText}\n\n` +
191|    `You are a reading companion for "${args.title}" by ${args.author}. ` +
