1|import "server-only";
2|import { randomUUID } from "node:crypto";
3|import {
4|  DAILY_IMAGE_LIMIT,
5|  MSG_CREDITS_OUT,
6|  MSG_FAILED,
7|  MSG_HUMAN,
8|  MSG_QUOTA,
9|  QUOTA_TTL_SEC,
10|  LOCK_TTL_SEC,
11|  buildCaption,
12|  buildPrompt,
13|  imageCostMicro,
14|  imageKey,
15|  indexKeyFor,
16|  lockKeyFor,
17|  quotaKeys,
18|} from "@/core/images";
19|import type { ImageGenerator, ImageRequest, ImageResponse, ImageStore } from "@/core/images";
20|import type { KV } from "@/core/types";
21|import { addRange, parseRanges, pickReusable, rangeListKeyFor } from "@/core/image-ranges";
22|import type { ParaRange } from "@/core/image-ranges";
23|import { buildChapterPrompt } from "@/core/panels";
24|import type { ImageEnv } from "./env";
25|import { errorTag } from "./errors";
26|import { checkHuman } from "@/server/guard/human";
27|import type { HumanCheckInput } from "@/server/guard/human";
28|import { refundDualQuota, takeDualQuota } from "@/server/guard/quota";
29|import { hashIp, ipBucket } from "@/server/guard/request";
30|import { reserveSpend } from "@/server/guard/spend";
31|import type { SpendReservation } from "@/server/guard/spend";
32|
33|export interface ImageContent {
34|  passageText: string;
35|  sceneTitle: string;
36|  sceneClip: string;
37|  // Chapter pages only: the panel descriptions, built server-side from
38|  // the chapter's scene summaries. sceneTitle carries the chapter title.
39|  chapterPanels?: { description: string }[];
40|}
41|
42|export interface OrchestrateDeps {
43|  kv: KV;
44|  store: ImageStore;
45|  generate: ImageGenerator;
46|  env: ImageEnv;
47|  content: ImageContent;
48|  ip: string;
49|  anonId: string;
50|  day: string;
51|  token?: string;
52|  // Scene holding the selection start; "" skips range reuse.
53|  sceneId: string;
54|  // Human gate, checked once on the cache-miss path after the lock.
55|  // Absent in tests that do not cover the check.
56|  human?: HumanCheckInput;
57|  // Receives the issued human cookie, if any; the handler sets it.
58|  humanOut?: { setCookie?: string };
59|}
60|
61|// One pass, no skipped steps: hit -> lock -> human -> quota -> budget ->
62|// generate -> store -> index -> release. Every failure after the reserve
63|// refunds quota, budget, and the daily counter and releases the lock.
64|export async function orchestrate(
65|  req: ImageRequest,
66|  deps: OrchestrateDeps,
67|): Promise<ImageResponse> {
68|  const key = imageKey(req);
69|  const indexKey = indexKeyFor(key);
70|  const lockKey = lockKeyFor(key);
71|
72|  // Passage range reuse: an overlapping cached selection serves this one.
73|  // Scene requests and unknown scenes skip all of it.
74|  let want: ParaRange | null = null;
75|  let rangesAt = "";
76|  let rangeList: ParaRange[] = [];
77|  if (req.kind === "passage" && deps.sceneId !== "") {
78|    want = { start: req.n, end: req.endN ?? req.n };
79|    rangesAt = rangeListKeyFor(req, deps.sceneId);
80|    rangeList = parseRanges(await deps.kv.get(rangesAt));
81|  }
82|  // shortcut: GET+SET can drop a concurrent append, which only costs a future reuse; upgrade to a Redis list if that matters.
83|  const recordRange = async (): Promise<void> => {
84|    const self = want;
85|    if (!self || rangeList.some((r) => r.start === self.start && r.end === self.end)) return;
86|    try {
87|      await deps.kv.set(rangesAt, JSON.stringify(addRange(rangeList, self)));
88|    } catch {
89|      console.error("image range index failed");
90|    }
91|  };
92|
93|  const indexed = await deps.kv.get(indexKey);
94|  if (indexed) {
95|    // Pictures cached before range reuse join the list on their next hit.
96|    await recordRange();
97|    return { status: "ready", url: indexed, cached: true, caption: captionFor(req, deps.content) };
98|  }
99|
100|  if (req.kind === "passage" && want) {
101|    const self = want;
102|    const best = pickReusable(
103|      rangeList.filter((r) => r.start !== self.start || r.end !== self.end),
104|      self,
105|    );
106|    if (best) {
107|      const bestKey = imageKey({ ...req, n: best.start, endN: best.end });
108|      const bestIndex = indexKeyFor(bestKey);
109|      let hit = await deps.kv.get(bestIndex);
110|      if (!hit) {
111|        hit = await deps.store.findUrl(bestKey);
112|        if (hit) await deps.kv.set(bestIndex, hit);
113|      }
114|      if (hit) {
115|        return { status: "ready", url: hit, cached: true, caption: captionFor(req, deps.content) };
116|      }
117|    }
118|  }
119|  const existing = await deps.store.findUrl(key);
120|  if (existing) {
121|    await deps.kv.set(indexKey, existing);
122|    await recordRange();
123|    return { status: "ready", url: existing, cached: true, caption: captionFor(req, deps.content) };
124|  }
125|
126|  const token = deps.token ?? randomUUID();
127|  if (!(await deps.kv.setNxEx(lockKey, token, LOCK_TTL_SEC))) return { status: "pending" };
128|
129|  // Best-effort unlock: a release failure must never turn into a client 500.
130|  const release = async (): Promise<void> => {
131|    try {
132|      await deps.kv.releaseIfToken(lockKey, token);
133|    } catch {
134|      // Lock expires on its own; nothing to do.
135|    }
136|  };
137|
138|  const keys = quotaKeys({
139|    day: deps.day,
140|    ipHash: hashIp(ipBucket(deps.ip, deps.anonId), deps.env.ipSalt),
141|    anonId: deps.anonId,
142|  });
143|  let quotaTaken = false;
144|  let reservation: SpendReservation | null = null;
145|  // Best-effort refunds that clear their flag only after the write lands,
146|  // so the outer catch refunds each reserve exactly once.
147|  const refundQuotaOnce = async (): Promise<void> => {
148|    if (quotaTaken) {
149|      await refundDualQuota(deps.kv, keys);
150|      quotaTaken = false;
151|    }
152|  };
153|  const releaseSpendOnce = async (): Promise<void> => {
154|    await reservation?.release();
155|    reservation = null;
156|  };
157|
158|  try {
159|    if (deps.human) {
160|      const human = await checkHuman(deps.human);
161|      if (!human.ok) {
162|        await release();
163|        return { status: "error", code: "human", message: MSG_HUMAN };
164|      }
165|      if (human.setCookie && deps.humanOut) deps.humanOut.setCookie = human.setCookie;
166|    }
167|
168|    const quota = await takeDualQuota(deps.kv, keys, {
169|      limit: DAILY_IMAGE_LIMIT,
170|      ttlSec: QUOTA_TTL_SEC,
171|    });
172|    if (!quota.ok) {
173|      await release();
174|      return { status: "error", code: "quota", message: MSG_QUOTA };
175|    }
176|    quotaTaken = true;
177|
178|    // Both caps apply only to requests paid with our key. The future
179|    // BYOK path must skip these reserves and check its own key instead.
180|    const spent = await reserveSpend(deps.kv, {
181|      amountMicro: imageCostMicro(),
182|      day: deps.day,
183|      spendCapMicro: deps.env.spendCapMicro,
184|      dailySpendCapMicro: deps.env.dailySpendCapMicro,
185|    });
186|    if (!spent.ok) {
187|      await releaseSpendOnce();
188|      await refundQuotaOnce();
189|      await release();
190|      return spent.which === "total"
191|        ? { status: "error", code: "budget", message: MSG_CREDITS_OUT }
192|        : { status: "error", code: "daily_budget", message: MSG_CREDITS_OUT };
193|    }
194|    reservation = spent.reservation;
195|
196|    let bytes: Uint8Array;
197|    try {
198|      bytes = await deps.generate.generate(
199|        req.kind === "chapter"
200|          ? buildChapterPrompt({
201|              chapterTitle: deps.content.sceneTitle,
202|              panels: deps.content.chapterPanels ?? [],
203|              style: req.style,
204|            })
205|          : buildPrompt({
206|              kind: req.kind,
207|              passageText: deps.content.passageText,
208|              sceneTitle: deps.content.sceneTitle,
209|              sceneClip: deps.content.sceneClip,
210|              style: req.style,
211|            }),
212|      );
213|    } catch (e) {
214|      await releaseSpendOnce();
215|      await refundQuotaOnce();
216|      await release();
217|      console.error(`image generate failed: ${errorTag(e)}`);
218|      return { status: "error", code: "unavailable", message: MSG_FAILED };
219|    }
220|
221|    try {
222|      const url = await deps.store.save(key, bytes);
223|      try {
224|        await deps.kv.set(indexKey, url);
225|      } catch {
226|        console.error("image index failed");
227|        await recordRange();
228|        await release();
229|        return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
230|      }
231|      await recordRange();
232|      await release();
233|      return { status: "ready", url, cached: false, caption: captionFor(req, deps.content) };
234|    } catch (e) {
235|      // A lost save race leaves the winner's file behind; backfill from it.
236|      const raced = await deps.store.findUrl(key);
237|      if (raced) {
238|        try {
239|          await deps.kv.set(indexKey, raced);
240|        } catch {
241|          console.error("image index failed");
242|        }
243|        await recordRange();
244|        await release();
245|        return { status: "ready", url: raced, cached: true, caption: captionFor(req, deps.content) };
246|      }
247|      await releaseSpendOnce();
248|      await refundQuotaOnce();
249|      await release();
250|      console.error(`image store failed: ${errorTag(e)}`);
251|      return { status: "error", code: "unavailable", message: MSG_FAILED };
252|    }
253|  } catch (e) {
254|    await releaseSpendOnce();
255|    await refundQuotaOnce();
256|    await release();
257|    console.error(`image request failed: ${errorTag(e)}`);
258|    return { status: "error", code: "unavailable", message: MSG_FAILED };
259|  }
260|}
261|
262|function captionFor(req: ImageRequest, content: ImageContent): string {
263|  return buildCaption({
264|    kind: req.kind,
265|    sceneTitle: content.sceneTitle,
266|    passageText: content.passageText,
267|  });
