1|// Track similarity and ranking. Pure: no env, no fetch, no audio.
2|import { EMOTIONS } from "./types";
3|import type { EmotionId, Vector8 } from "./types";
4|import { buildFeatures } from "./cluster";
5|import type {
6|  MusicConfig,
7|  MusicWeights,
8|  SceneSignal,
9|  Similarity,
10|  Track,
11|} from "./music-types";
12|
13|// Renormalize the 8 entries to sum 1. Extra keys (such as a Jev
14|// "unknown" entry) are ignored. An all-zero vector stays all zero.
15|export function normalize8(vector: Record<string, number>): number[] {
16|  const values = EMOTIONS.map((id: EmotionId) => {
17|    const v = vector[id];
18|    return typeof v === "number" && Number.isFinite(v) ? v : 0;
19|  });
20|  const sum = values.reduce((a, b) => a + b, 0);
21|  if (sum <= 0) return values.map(() => 0);
22|  return values.map((v) => v / sum);
23|}
24|
25|// Bhattacharyya affinity over the renormalized shapes, plus separate
26|// intensity and tempo terms. Fair to blended scenes, unlike cosine.
27|export function bhattacharyyaSimilarity(
28|  scene: SceneSignal,
29|  track: Track,
30|  weights: MusicWeights = MUSIC_CONFIG.weights,
31|): number {
32|  const s = normalize8(scene.vector);
33|  const t = normalize8(track.vector);
34|  let affinity = 0;
35|  for (let i = 0; i < s.length; i++) {
36|    affinity += Math.sqrt((s[i] ?? 0) * (t[i] ?? 0));
37|  }
38|  return (
39|    weights.emotion * affinity +
40|    weights.intensity * (1 - Math.abs(scene.intensity - track.intensity)) +
41|    weights.tempo * (1 - Math.abs(scene.tempo - track.tempo))
42|  );
43|}
44|
45|// Cosine over buildFeatures output (vector plus weighted intensity and
46|// tempo). Kept as an alternative; it favors peaky scenes.
47|export function cosineSimilarity(scene: SceneSignal, track: Track): number {
48|  const a = buildFeatures(scene);
49|  const b = buildFeatures(track);
50|  let dot = 0;
51|  let na = 0;
52|  let nb = 0;
53|  for (let i = 0; i < a.length; i++) {
54|    const x = a[i] ?? 0;
55|    const y = b[i] ?? 0;
56|    dot += x * y;
57|    na += x * x;
58|    nb += y * y;
59|  }
60|  if (na === 0 || nb === 0) return 0;
61|  return dot / (Math.sqrt(na) * Math.sqrt(nb));
62|}
63|
64|export const MUSIC_CONFIG: MusicConfig = {
65|  similarity: bhattacharyyaSimilarity,
66|  weights: { emotion: 0.7, intensity: 0.15, tempo: 0.15 },
67|  dwellSec: 20,
68|  sceneEntryDwellSec: 5,
69|  minTrackSec: 45,
70|  crossfadeSec: 3,
71|  // Admits near ties into the random-mode draw without letting clearly
72|  // worse matches in.
73|  randomTolerance: 0.05,
74|};
75|
76|export function resolveConfig(override?: Partial<MusicConfig>): MusicConfig {
77|  if (!override) return MUSIC_CONFIG;
78|  return {
79|    ...MUSIC_CONFIG,
80|    ...override,
81|    weights: override.weights ?? MUSIC_CONFIG.weights,
82|  };
83|}
84|
85|export function scoreTrack(
86|  scene: SceneSignal,
87|  track: Track,
88|  override?: Partial<MusicConfig>,
89|): number {
90|  const config = resolveConfig(override);
91|  return config.similarity(scene, track, config.weights);
92|}
93|
94|// One id tie-break for every ranking. Lower id wins, so ranking is stable.
95|export function compareTrackId(a: { id: string }, b: { id: string }): number {
96|  return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
97|}
98|
99|export interface RankedTrack {
100|  track: Track;
101|  score: number;
102|}
103|
104|// One ranking core: each track scored once, best first, ties to lower id.
105|export function rankScored(
106|  scene: SceneSignal,
107|  tracks: Track[],
108|  override?: Partial<MusicConfig>,
109|): RankedTrack[] {
110|  const config = resolveConfig(override);
111|  return tracks
112|    .map((track) => ({ track, score: config.similarity(scene, track, config.weights) }))
113|    .sort((a, b) => b.score - a.score || compareTrackId(a.track, b.track));
114|}
115|
116|// Dominant emotion of a scene: argmax of the renormalized vector, with
117|// ties broken by EMOTIONS order.
118|export function dominantEmotion(scene: SceneSignal): EmotionId {
119|  const norm = normalize8(scene.vector);
120|  let best: EmotionId = EMOTIONS[0] as EmotionId;
121|  let bestValue = -Infinity;
122|  EMOTIONS.forEach((id: EmotionId, i: number) => {
123|    const value = norm[i] ?? 0;
124|    if (value > bestValue) {
125|      bestValue = value;
126|      best = id;
127|    }
128|  });
129|  return best;
130|}

