1|// CLI: npm run build:book -- oz [--step ingest|segment|classify|resplit|cluster|narrate] [--force] [--dry-run]
2|// --dry-run prints one freshness line per selected step and stops before
3|// any client, write, or network call.
4|import { readFileSync } from "node:fs";
5|import { join } from "node:path";
6|import { runClassify } from "./classify";
7|import { createCleanJudgeFromEnv } from "./clean-providers";
8|import { runCluster } from "./cluster-tracks";
9|import { bookConfig, runIngest } from "./ingest";
10|import type { StepCtx } from "./ingest";
11|import { planSteps } from "./freshness";
12|import type { FreshStep } from "./freshness";
13|import { createJevClient } from "./jev";
14|import { createMetaClient } from "./meta";
15|import { runNarrate } from "./narrate";
16|import { runResplit } from "./resplit";
17|import { runSegment } from "./segment";
18|
19|const STEPS = ["ingest", "segment", "classify", "resplit", "cluster", "narrate"] as const;
20|
21|function loadEnv(): void {
22|  try {
23|    if (typeof process.loadEnvFile === "function") process.loadEnvFile(".env.local");
24|  } catch {
25|    // No .env.local is fine; env may come from elsewhere.
26|  }
27|}
28|
29|function env(name: string, fallback?: string): string {
30|  const value = process.env[name] ?? fallback;
31|  if (value === undefined || value === "") throw new Error(`${name} is not set`);
32|  return value;
33|}
34|
35|async function main(): Promise<void> {
36|  loadEnv();
37|  const args = process.argv.slice(2);
38|  const bookKey = args.find((a) => !a.startsWith("--")) ?? "";
39|  const stepFlag = args.indexOf("--step");
40|  const stepArg = stepFlag === -1 ? undefined : args[stepFlag + 1];
41|  const force = args.includes("--force");
42|  const dryRun = args.includes("--dry-run");
43|  if (!bookKey) throw new Error("usage: build:book <book> [--step ingest|segment|classify|resplit|cluster|narrate] [--force] [--dry-run]");
44|  bookConfig(bookKey); // fails fast on unknown keys with the valid list
45|  const only = stepArg ?? "";
46|  if (only !== "" && !(STEPS as readonly string[]).includes(only)) {
47|    throw new Error(`unknown step "${only}", valid steps: ${STEPS.join(", ")}`);
48|  }
49|  const ctx: StepCtx = { bookKey, force, dir: join("data", "books", bookKey) };
50|  if (dryRun) {
51|    const selected = (only === "" ? [...STEPS] : [only]) as (typeof STEPS)[number][];
52|    if (selected.includes("ingest")) console.log("ingest: not checked in dry run (frozen textVersion rule)");
53|    for (const plan of planSteps(ctx.dir, selected.filter((s): s is FreshStep => s !== "ingest"), force)) {
54|      console.log(`${plan.step}: ${plan.reuse ? "reuse" : "redo"} (${plan.reason})`);
55|    }
56|    return;
57|  }
58|  const run: Record<(typeof STEPS)[number], boolean> = {
59|    ingest: only === "" || only === "ingest",
60|    segment: only === "" || only === "segment",
61|    classify: only === "" || only === "classify",
62|    resplit: only === "" || only === "resplit",
63|    cluster: only === "" || only === "cluster",
64|    narrate: only === "" || only === "narrate",
65|  };
66|  if (run.ingest) {
67|    const epub = bookConfig(bookKey).format === "epub";
68|    const judge = epub ? createCleanJudgeFromEnv() : undefined;
69|    const book = await runIngest(ctx, { judge });
70|    console.log(`ingest: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${book.textVersion}`);
71|  }
72|  if (run.segment) {
73|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
74|    console.log(`segment: ${meta.model}`);
75|    const scenes = await runSegment(ctx, { meta });
76|    console.log(`segment: ${scenes.length} scenes`);
77|  }
78|  if (run.classify) {
79|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
80|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
81|    const scenes = await runClassify(ctx, { jev, meta });
82|    const overrides = scenes.filter((s) => s.muse_override !== null).length;
83|    const failures = scenes.filter((s) => s.final === null).length;
84|    console.log(`classify: ${scenes.length} scenes, ${overrides} overrides, ${failures} failures`);
85|  }
86|  if (run.resplit) {
87|    const meta = createMetaClient({ apiKey: env("META_API_KEY"), model: process.env.META_MODEL ?? "muse-spark-1.3-contributor" });
88|    const jev = createJevClient({ apiKey: env("JEV_API_KEY"), model: process.env.JEV_MODEL ?? "jev-1.14.0" });
89|    const scenes = await runResplit(ctx, { jev, meta });
90|    console.log(`resplit: ${scenes.length} scenes`);
91|  }
92|  if (run.cluster) {
93|    await runCluster(ctx);
94|    console.log("cluster: wrote music-clusters.json");
95|  }
96|  if (run.narrate) {
97|    // The Kokoro client loads lazily only when this step runs, so the
98|    // other steps never touch Modal. Narration needs neither
99|    // META_API_KEY nor JEV_API_KEY.
100|    const { createKokoroClient } = await import("./kokoro");
101|    const client = createKokoroClient();
102|    await runNarrate(ctx, { synthesize: (req) => client.synthesize(req) });
103|  }
104|  printSummary(ctx.dir);
105|}
106|
