109|    chapters: unknown[];
110|    paragraphs: unknown[];
111|  };
112|  let scenes: { final: { vector: Record<string, number> } | null }[] = [];
113|  let overrideRate = 0;
114|  let jev = { cost_usd: 0 };
115|  let meta = { cost_usd: 0 };
116|  let total = 0;
117|  try {
118|    const analysis = JSON.parse(readFileSync(join(dir, "analysis.json"), "utf8")) as {
119|      scenes: (typeof scenes)[number][];
120|      override_rate: number;
121|      provenance: { jev: typeof jev; meta: typeof meta; total_cost_usd: number };
122|    };
123|    scenes = analysis.scenes;
124|    overrideRate = analysis.override_rate;
125|    jev = analysis.provenance.jev;
126|    meta = analysis.provenance.meta;
127|    total = analysis.provenance.total_cost_usd;
128|  } catch {
