132|  let failures = 0;
133|  for (const scene of scenes) {
134|    if (!scene.final) {
135|      failures += 1;
136|      continue;
137|    }
138|    const top = Object.entries(scene.final.vector).sort((a, b) => b[1] - a[1])[0]?.[0] ?? "?";
139|    dist.set(top, (dist.get(top) ?? 0) + 1);
140|  }
141|  console.log(`summary: ${book.chapters.length} chapters, ${book.paragraphs.length} paragraphs, ${scenes.length} scenes`);
142|  console.log(`emotions: ${[...dist.entries()].map(([id, count]) => `${id} ${count}`).join(", ") || "none yet"}`);
143|  console.log(`override rate ${((overrideRate ?? 0) * 100).toFixed(1)}%, failures ${failures}`);
144|  console.log(`cost: jev $${(jev.cost_usd ?? 0).toFixed(4)}, meta $${(meta.cost_usd ?? 0).toFixed(4)}, total $${(total ?? 0).toFixed(4)}`);
145|}
146|
147|main().catch((error: unknown) => {
148|  console.error(`error: ${(error as Error).message}`);
149|  process.exit(1);
150|});

