1|// Converter: Martin's etiquetar.html export plus the box-side library file
2|// become public/music/manifest.json. The transform is pure; the CLI at the
3|// bottom is a thin shell. Diagnostics go to stderr, JSON to stdout or --out.
4|import { readFileSync, writeFileSync } from "node:fs";
