60|interface Library {
61|  styles: StyleInfo[];
62|  soundtracks: { id: string; name: string; style: string; credit?: string }[];
63|  entries: Record<string, LibraryEntry>;
64|  extraTracks: unknown[];
65|  playlists: Playlist[];
66|}
67|
68|function isRecord(value: unknown): value is Record<string, unknown> {
69|  return typeof value === "object" && value !== null && !Array.isArray(value);
70|}
71|
72|function isEmotion(value: unknown): value is EmotionId {
73|  return typeof value === "string" && (EMOTIONS as readonly string[]).includes(value);
74|}
75|
76|type ExportStatus = "todo" | "validated" | "relabeled" | "discarded";
77|
78|function isStatus(value: unknown): value is ExportStatus {
79|  return value === "todo" || value === "validated" || value === "relabeled" || value === "discarded";
80|}
81|
82|function reqString(entry: Record<string, unknown>, key: string, what: string): string {
83|  const value = entry[key];
84|  if (typeof value !== "string" || value === "") throw new Error(`${what} needs a non-empty ${key}`);
85|  return value;
86|}
87|
88|function optString(entry: Record<string, unknown>, key: string, what: string): string | undefined {
89|  const value = entry[key];
90|  if (value === undefined) return undefined;
91|  if (typeof value !== "string" || value === "") throw new Error(`${what} ${key} must be a non-empty string`);
92|  return value;
93|}
94|
95|function reqFinite(entry: Record<string, unknown>, key: string, what: string): number {
96|  const value = entry[key];
97|  if (typeof value !== "number" || !Number.isFinite(value)) {
98|    throw new Error(`${what} ${key} must be a finite number`);
99|  }
100|  return value;
101|}
102|
103|function parseLabels(json: unknown): { tracks: ExportTrack[]; segments: ExportSegment[] } {
104|  if (!isRecord(json)) throw new Error("labels export must be an object");
105|  if (json.schemaVersion !== 2) {
106|    throw new Error(`labels export schemaVersion must be 2, got ${String(json.schemaVersion)}`);
107|  }
108|  if (!Array.isArray(json.tracks)) throw new Error("labels export tracks must be an array");
109|  if (!Array.isArray(json.segments)) throw new Error("labels export segments must be an array");
110|  const tracks = json.tracks.map((entry, i) => {
111|    if (!isRecord(entry)) throw new Error(`labels track ${i} must be an object`);
112|    const trackId = reqString(entry, "trackId", `labels track ${i}`);
113|    const status = entry.status;
114|    if (!isStatus(status)) {
115|      throw new Error(`labels track ${trackId} has unknown status ${String(status)}`);
116|    }
117|    const style = optString(entry, "style", `labels track ${trackId}`);
118|    return { trackId, status, ...(style === undefined ? {} : { style }) };
119|  });
120|  const segments = json.segments.map((entry, i) => {
121|    if (!isRecord(entry)) throw new Error(`labels segment ${i} must be an object`);
122|    const trackId = reqString(entry, "trackId", `labels segment ${i}`);
123|    const segmentId = reqString(entry, "segmentId", `labels segment ${i}`);
124|    const what = `segment ${segmentId}`;
125|    const startSec = reqFinite(entry, "startSec", what);
126|    const endSec = reqFinite(entry, "endSec", what);
127|    if (startSec < 0 || endSec <= startSec) throw new Error(`${what} needs 0 <= startSec < endSec`);
128|    const primary = entry.primary;
129|    if (!isEmotion(primary)) throw new Error(`${what} primary must be one of the 8 emotion ids`);
130|    let vector: Vector8 | undefined;
131|    if (entry.vector !== undefined) {
132|      if (!isRecord(entry.vector)) throw new Error(`${what} vector must be an object`);
133|      const out = {} as Record<EmotionId, number>;
134|      for (const id of EMOTIONS) {
135|        const raw = entry.vector[id];
136|        if (raw === undefined) {
137|          out[id] = 0;
138|        } else {
139|          if (typeof raw !== "number" || !Number.isFinite(raw)) {
140|            throw new Error(`${what} vector ${id} must be a finite number`);
141|          }
142|          out[id] = Math.round(Math.min(1, Math.max(0, raw)) * 1000) / 1000;
143|        }
144|      }
145|      vector = out as Vector8;
146|    }
147|    const level = (key: string): number => {
148|      const n = reqFinite(entry, key, what);
149|      if (!Number.isInteger(n) || n < 1 || n > 5) throw new Error(`${what} ${key} must be an integer 1..5`);
150|      return n;
151|    };
152|    return {
153|      trackId,
154|      segmentId,
155|      startSec,
156|      endSec,
157|      primary,
158|      ...(vector === undefined ? {} : { vector }),
159|      intensity: level("intensity"),
160|      tempo: level("tempo"),
161|    };
162|  });
163|  return { tracks, segments };
