187|    const durationSec = reqFinite(raw, "durationSec", what);
188|    if (durationSec <= 0) throw new Error(`${what} durationSec must be positive`);
189|    const gainDb = raw.gainDb;
190|    if (gainDb !== undefined && (typeof gainDb !== "number" || !Number.isFinite(gainDb))) {
191|      throw new Error(`${what} gainDb must be a finite number`);
192|    }
193|    const noDerivatives = raw.noDerivatives;
194|    if (noDerivatives !== undefined && typeof noDerivatives !== "boolean") {
195|      throw new Error(`${what} noDerivatives must be a boolean`);
196|    }
197|    const source = raw.source;
198|    if (source !== undefined && source !== "generated" && source !== "jamendo" && source !== "recording") {
199|      throw new Error(`${what} source must be generated, jamendo, or recording`);
200|    }
201|    entries[trackId] = {
202|      src: reqString(raw, "src", what),
203|      soundtrack: reqString(raw, "soundtrack", what),
204|      durationSec,
205|      title: reqString(raw, "title", what),
206|      ...(noDerivatives === undefined ? {} : { noDerivatives }),
207|      ...(gainDb === undefined ? {} : { gainDb }),
208|      ...(source === undefined ? {} : { source }),
209|    };
210|    for (const key of ["composer", "artist", "license", "attribution", "sourceUrl", "fallbackSrc"] as const) {
211|      const value = optString(raw, key, what);
212|      if (value !== undefined) entries[trackId]![key] = value;
213|    }
214|  }
215|  const extraTracks = json.extraTracks ?? [];
216|  if (!Array.isArray(extraTracks)) throw new Error("library extraTracks must be an array");
217|  return {
218|    styles: json.styles as StyleInfo[],
219|    soundtracks,
220|    entries,
