140|            throw new Error(`${what} vector ${id} must be a finite number`);
141|          }
142|          out[id] = Math.round(Math.min(1, Math.max(0, raw)) * 1000) / 1000;
143|        }
144|      }
145|      vector = out as Vector8;
146|    }
147|    const level = (key: string): number => {
148|      const n = reqFinite(entry, key, what);
149|      if (!Number.isInteger(n) || n < 1 || n > 5) throw new Error(`${what} ${key} must be an integer 1..5`);
150|      return n;
151|    };
152|    return {
153|      trackId,
154|      segmentId,
155|      startSec,
156|      endSec,
157|      primary,
158|      ...(vector === undefined ? {} : { vector }),
159|      intensity: level("intensity"),
160|      tempo: level("tempo"),
161|    };
162|  });
163|  return { tracks, segments };
164|}
