170|  if (!Array.isArray(json.soundtracks)) throw new Error("library soundtracks must be an array");
171|  if (!Array.isArray(json.playlists ?? [])) throw new Error("library playlists must be an array");
172|  const soundtracks = json.soundtracks.map((entry, i) => {
173|    if (!isRecord(entry)) throw new Error(`library soundtrack ${i} must be an object`);
174|    const credit = optString(entry, "credit", `library soundtrack ${entry.id ?? i}`);
175|    return {
176|      id: reqString(entry, "id", `library soundtrack ${i}`),
177|      name: reqString(entry, "name", `library soundtrack ${i}`),
178|      style: reqString(entry, "style", `library soundtrack ${i}`),
179|      ...(credit === undefined ? {} : { credit }),
180|    };
181|  });
182|  if (!isRecord(json.entries)) throw new Error("library entries must be an object");
183|  const entries: Record<string, LibraryEntry> = {};
184|  for (const [trackId, raw] of Object.entries(json.entries)) {
185|    if (!isRecord(raw)) throw new Error(`library entry ${trackId} must be an object`);
