1|// `vercel env pull` writes Sensitive vars as "[SENSITIVE]".
2|export function usable(raw: string | undefined): string | undefined {
3|  if (raw === undefined || raw === "") return undefined;
4|  if (/^\[[A-Z_]+\]$/.test(raw.trim())) return undefined;
5|  return raw;
6|}
7|
8|export interface TurnstilePair {
9|  turnstileSecret?: string;
10|  turnstileSiteKey?: string;
11|}
12|
13|// Placeholders filtered so a pulled "[SENSITIVE]" secret never turns the check on.
14|export function turnstilePair(from: NodeJS.ProcessEnv): TurnstilePair {
15|  const secret = usable(from.TURNSTILE_SECRET_KEY);
16|  const siteKey = usable(from.NEXT_PUBLIC_TURNSTILE_SITE_KEY);
17|  return {
18|    ...(secret ? { turnstileSecret: secret } : {}),
19|    ...(siteKey ? { turnstileSiteKey: siteKey } : {}),
20|  };
21|}
22|
23|// One rule for both spend caps: a finite, non-negative USD value wins,
24|// anything else (missing, blank, non-numeric, negative, Infinity) falls back.
25|// Zero stays valid so a zero cap can intentionally block spend.
26|export function parseCapUsd(raw: string | undefined, fallback: number): number {
27|  if (raw === undefined || raw.trim() === "") return fallback;
28|  const value = Number(raw);
29|  return Number.isFinite(value) && value >= 0 ? value : fallback;
