290|// In-memory KV for tests. Expiries are checked against Date.now.
291|export function createMemoryKV(): KV & { clear(): void } {
292|  const values = new Map<string, string>();
293|  const expiresAt = new Map<string, number>();
294|  function live(key: string): boolean {
295|    const until = expiresAt.get(key);
296|    if (until !== undefined && Date.now() >= until) {
297|      values.delete(key);
298|      expiresAt.delete(key);
299|      return false;
