212|  return `img:lock:${key}`;
213|}
214|
215|export function quotaKeys(args: { day: string; ipHash: string; anonId: string }): {
216|  ip: string;
217|  anon: string;
218|} {
219|  return {
220|    ip: `img:quota:ip:${args.day}:${args.ipHash}`,
221|    anon: `img:quota:anon:${args.day}:${args.anonId}`,
222|  };
223|}
224|
225|export function overQuota(count: number): boolean {
226|  return count > DAILY_IMAGE_LIMIT;
227|}
228|
229|export function imageCostMicro(): number {
230|  return IMAGE_COST_MICRO;
231|}
232|
233|// Lets the route compare lock tokens without touching Redis twice.
234|export function canRelease(expected: string, actual: string | null): boolean {
235|  return actual !== null && actual === expected;
236|}
237|
238|export function clipText(text: string, max: number): string {
239|  const clean = text.replace(/\s+/g, " ").trim();
240|  if (clean.length <= max) return clean;
241|  return clean.slice(0, max).trimEnd();
242|}
243|
244|// The illustration style line, shared by scene and chapter prompts: the
245|// Denslow sentence by default, the parsed style's descriptor otherwise.
246|export function styleLine(style: ImageStyle | undefined): string {
247|  if (style !== undefined) return styleDescriptorLine(style);
248|  return (
249|    "Illustration in the style of W. W. Denslow's 1900 first-edition " +
250|    "illustrations for The Wonderful Wizard of Oz: flat color, bold black " +
251|    "ink outlines, limited palette. Dorothy wears silver shoes. Nothing " +
252|    "from the 1939 MGM film, no ruby slippers, no film look. No text, " +
253|    "no captions, no lettering in the image."
254|  );
