258|// ordinals and ids, never free text, so there is no injection path. Only
259|// the optional parsed style reaches the prompt, never raw client text.
260|export function buildPrompt(args: {
261|  kind: Exclude<ImageKind, "chapter">;
262|  passageText: string;
263|  sceneTitle: string;
264|  sceneClip: string;
265|  style?: ImageStyle;
266|}): string {
267|  const style = styleLine(args.style);
268|  if (args.kind === "scene") {
269|    return (
270|      `Scene "${args.sceneTitle}". ${clipText(args.sceneClip, MAX_SCENE_CLIP_CHARS)}. ${style}`
271|    );
272|  }
273|  return (
274|    `Scene "${args.sceneTitle}". Passage: ${clipText(args.passageText, MAX_PASSAGE_CHARS)}. ` +
275|    `Context: ${clipText(args.sceneClip, MAX_SCENE_CLIP_CHARS)}. ${style}`
276|  );
277|}
