279|export function buildCaption(args: {
280|  kind: ImageKind;
281|  sceneTitle: string;
282|  passageText: string;
283|}): string {
284|  if (args.kind === "scene" || args.kind === "chapter") return args.sceneTitle;
285|  const words = args.passageText.replace(/\s+/g, " ").trim().split(" ").slice(0, 10);
286|  const head = words.join(" ");
287|  return words.length >= 10 ? `${head}…` : head;
