289|
290|// In-memory KV for tests. Expiries are checked against Date.now.
291|export function createMemoryKV(): KV & { clear(): void } {
292|  const values = new Map<string, string>();
293|  const expiresAt = new Map<string, number>();
294|  function live(key: string): boolean {
295|    const until = expiresAt.get(key);
296|    if (until !== undefined && Date.now() >= until) {
297|      values.delete(key);
298|      expiresAt.delete(key);
299|      return false;
300|    }
301|    return true;
302|  }
303|  function num(key: string): number {
304|    return Number(values.get(key) ?? "0");
305|  }
306|  return {
307|    async get(key: string): Promise<string | null> {
308|      if (!live(key)) return null;
309|      return values.get(key) ?? null;
310|    },
311|    async setNxEx(key: string, value: string, exSec: number): Promise<boolean> {
312|      if (live(key) && values.has(key)) return false;
313|      values.set(key, value);
314|      expiresAt.set(key, Date.now() + exSec * 1000);
315|      return true;
316|    },
317|    async set(key: string, value: string): Promise<void> {
318|      values.set(key, value);
319|      expiresAt.delete(key);
320|    },
321|    async incr(key: string): Promise<number> {
322|      const next = num(key) + 1;
323|      values.set(key, String(next));
324|      return next;
325|    },
326|    async incrBy(key: string, by: number): Promise<number> {
327|      const next = num(key) + by;
328|      values.set(key, String(next));
329|      return next;
330|    },
331|    async decr(key: string): Promise<number> {
332|      const next = num(key) - 1;
333|      values.set(key, String(next));
334|      return next;
335|    },
336|    async decrBy(key: string, by: number): Promise<number> {
337|      const next = num(key) - by;
338|      values.set(key, String(next));
339|      return next;
340|    },
341|    async expire(key: string, sec: number): Promise<void> {
342|      if (values.has(key)) expiresAt.set(key, Date.now() + sec * 1000);
343|    },
344|    async releaseIfToken(key: string, token: string): Promise<boolean> {
345|      if (!live(key)) return false;
346|      if (values.get(key) !== token) return false;
347|      values.delete(key);
348|      expiresAt.delete(key);
349|      return true;
350|    },
351|    clear(): void {
352|      values.clear();
353|      expiresAt.clear();
354|    },
355|  };
