6|// Meta image client. Reads no env: the caller passes the key in, and
7|// tests inject a fake generator instead of this module. The 100 s budget
8|// leaves room inside the 120 s route for Blob, quota, and the refund.
9|export function createMetaClient(apiKey: string): ImageGenerator {
