17|          prompt,
18|          n: 1,
19|          size: "1024x1024",
20|          output_format: "webp",
21|          response_format: "b64_json",
22|        }),
23|        signal: AbortSignal.timeout(100_000),
24|      });
25|      if (!res.ok) throw new Error(`meta status ${res.status}`);
26|      const json = (await res.json()) as { data?: Array<{ b64_json?: string }> };
27|      const b64 = json.data?.[0]?.b64_json;
28|      if (!b64) throw new Error("meta empty image");
29|      return new Uint8Array(Buffer.from(b64, "base64"));
