20|  stream(args: { messages: UpstreamMessage[]; signal?: AbortSignal }): AsyncIterable<ChatStreamChunk>;
21|}
22|
23|// Meta streaming client. Errors carry only the status number or a timeout
24|// word: never the key, the prompt, or upstream response text.
25|export function createChatStreamer(args: {
26|  apiKey: string;
27|  fetchFn?: typeof fetch;
28|  firstTokenTimeoutMs?: number;
29|  totalTimeoutMs?: number;
30|}): ChatStreamer {
31|  const fetchFn = args.fetchFn ?? fetch;
32|  const firstMs = args.firstTokenTimeoutMs ?? FIRST_TOKEN_TIMEOUT_MS;
33|  const totalMs = args.totalTimeoutMs ?? TOTAL_TIMEOUT_MS;
34|
35|  return {
36|    stream({ messages, signal }: { messages: UpstreamMessage[]; signal?: AbortSignal }) {
37|      return (async function* (): AsyncGenerator<ChatStreamChunk> {
38|        const ctrl = new AbortController();
39|        let timedOut: "first-token" | "total" | null = null;
40|        const onCallerAbort = (): void => ctrl.abort();
41|        if (signal?.aborted) ctrl.abort();
42|        else signal?.addEventListener("abort", onCallerAbort, { once: true });
43|        const firstTimer = setTimeout(() => {
44|          timedOut = "first-token";
45|          ctrl.abort();
46|        }, firstMs);
47|        const totalTimer = setTimeout(() => {
48|          timedOut = "total";
49|          ctrl.abort();
50|        }, totalMs);
51|        let reader: ReadableStreamDefaultReader<Uint8Array> | null = null;
52|        const cancelOnAbort = (): void => {
53|          reader?.cancel().catch(() => {});
54|        };
55|        ctrl.signal.addEventListener("abort", cancelOnAbort);
56|        const fail = (cause: unknown): Error => {
57|          if (signal?.aborted && !timedOut) {
58|            return cause instanceof Error ? cause : new Error("chat upstream aborted");
59|          }
60|          if (timedOut) return new Error(`chat upstream ${timedOut} timeout`);
