18|  const { book, scenes } = loadOzBook();
19|  const model = buildReaderModel(book, { scenes });
20|  const panelsByChapter = model.chapters.map((chapter) => ({
21|    ch: chapter.ch,
22|    panels: chapterPanels(scenes.filter((s) => s.ch === chapter.ch)).map((g, i) => ({
23|      key: g.sceneIds[0] ?? `p${i + 1}`,
24|      caption: g.caption,
25|    })),
26|  }));
27|  return <BookView model={model} initialSceneId={sceneId} panelsByChapter={panelsByChapter} />;
28|}

