151|export function deriveTitle(sec: Pick<RawSection, "blocks" | "docTitle" | "navLabel">, bookTitle: string): string {
152|  const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.trim());
153|  const first = heads.find((h) => h.toLowerCase() !== bookTitle.toLowerCase());
154|  if (first === undefined) return sec.docTitle ?? sec.navLabel ?? "Untitled";
155|  const stripped = first
156|    .replace(/^(?:chapter|stave|book|part)\s+[ivxlc0-9]+[.:]?\s*/i, "")
157|    .replace(/^(?:[ivxlc]+|\d+)[.:]?\s+/i, "")
158|    .trim();
159|  if (stripped.length > 0) return stripped;
160|  if (sec.navLabel !== null) {
161|    const colon = sec.navLabel.indexOf(":");
162|    if (colon !== -1 && sec.navLabel.slice(colon + 1).trim().length > 0) {
163|      return sec.navLabel.slice(colon + 1).trim();
164|    }
165|  }
166|  return sec.docTitle ?? sec.navLabel ?? "Untitled";
167|}
168|
169|// Rule 5: front-matter titles. Besides the guess, a bare heading such as
170|// "Contents" on a title page drops the section.
171|export function ruleTitlePolicy(bookTitle: string) {
172|  return (sec: RawSection): { kind: string; reason: string } | null => {
173|    const hit = matchTitleTerm(deriveTitle(sec, bookTitle));
174|    if (hit !== null) {
175|      // A title guessed from the nav label (no headings, no docTitle) gets
176|      // the pg-markers guard: a long story body keeps its chapter.
177|      const viaNav = sec.docTitle === null && sec.navLabel !== null && !sec.blocks.some((b) => b.heading);
178|      if (viaNav && (isConfident(sec) || nonMarkerWords(sec) > 300)) return null;
179|      return hit;
180|    }
181|    const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.toLowerCase().trim());
182|    for (const { term, kind } of TITLE_TERMS) {
183|      if (heads.includes(term)) return { kind, reason: `heading matches "${term}"` };
184|    }
185|    return null;
186|  };
187|}
188|
189|// Case- and punctuation-insensitive title compare for contents lists and
190|// duplicate title blocks.
191|function normalizeTitle(text: string): string {
192|  return text
193|    .toLowerCase()
194|    .replace(/[^\p{L}\p{N}\s]/gu, "")
195|    .replace(/\s+/g, " ")
196|    .trim();
197|}
198|
199|// Rule 6: contents tables are mostly short entries plus page numbers, or a
200|// cross-reference list of the book's own chapter titles (pg54 h-0): at
201|// least 3 non-empty blocks, at least half, equal other sections' derived
202|// titles or first headings.
203|export function ruleContentsBody(bookTitle: string, sections: RawSection[]) {
204|  const titles = new Set<string>();
205|  for (const sec of sections) {
206|    titles.add(normalizeTitle(deriveTitle(sec, bookTitle)));
207|    const firstHead = sec.blocks.find((b) => b.heading);
208|    if (firstHead !== undefined) titles.add(normalizeTitle(firstHead.text));
209|  }
210|  titles.delete("");
211|  return (sec: RawSection): { kind: string; reason: string } | null => {
212|    const body = sec.blocks.filter((b) => !b.heading);
213|    if (body.length > 0) {
214|      const shortCount = body.filter((b) => countWords(b.text) < 6).length;
215|      const numbers = body.filter((b) => /^\d+$/.test(b.text.trim())).length;
216|      if (shortCount / body.length >= 0.6 && numbers >= 3) {
217|        return { kind: "contents", reason: "mostly short entries with page numbers" };
218|      }
219|    }
220|    const nonEmpty = sec.blocks.filter((b) => b.text.trim().length > 0);
221|    if (nonEmpty.length === 0) return null;
222|    const mine = new Set([normalizeTitle(deriveTitle(sec, bookTitle))]);
223|    const firstHead = sec.blocks.find((b) => b.heading);
224|    if (firstHead !== undefined) mine.add(normalizeTitle(firstHead.text));
225|    const hits = nonEmpty.filter((b) => {
226|      const text = normalizeTitle(b.text);
227|      return text.length > 0 && titles.has(text) && !mine.has(text);
228|    }).length;
229|    if (hits >= 3 && hits / nonEmpty.length >= 0.5) {
230|      return { kind: "contents", reason: "lists other sections' titles" };
231|    }
232|    return null;
233|  };
