151|export function deriveTitle(sec: Pick<RawSection, "blocks" | "docTitle" | "navLabel">, bookTitle: string): string {
152|  const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.trim());
153|  const first = heads.find((h) => h.toLowerCase() !== bookTitle.toLowerCase());
154|  if (first === undefined) return sec.docTitle ?? sec.navLabel ?? "Untitled";
155|  const stripped = first
156|    .replace(/^(?:chapter|stave|book|part)\s+[ivxlc0-9]+[.:]?\s*/i, "")
157|    .replace(/^(?:[ivxlc]+|\d+)[.:]?\s+/i, "")
158|    .trim();
159|  if (stripped.length > 0) return stripped;
160|  if (sec.navLabel !== null) {
161|    const colon = sec.navLabel.indexOf(":");
162|    if (colon !== -1 && sec.navLabel.slice(colon + 1).trim().length > 0) {
163|      return sec.navLabel.slice(colon + 1).trim();
164|    }
165|  }
166|  return sec.docTitle ?? sec.navLabel ?? "Untitled";
167|}
168|
169|// Rule 5: front-matter titles. Besides the guess, a bare heading such as
170|// "Contents" on a title page drops the section.
171|export function ruleTitlePolicy(bookTitle: string) {
172|  return (sec: RawSection): { kind: string; reason: string } | null => {
173|    const hit = matchTitleTerm(deriveTitle(sec, bookTitle));
174|    if (hit !== null) {
175|      // A title guessed from the nav label (no headings, no docTitle) gets
176|      // the pg-markers guard: a long story body keeps its chapter.
177|      const viaNav = sec.docTitle === null && sec.navLabel !== null && !sec.blocks.some((b) => b.heading);
178|      if (viaNav && (isConfident(sec) || nonMarkerWords(sec) > 300)) return null;
179|      return hit;
180|    }
181|    const heads = sec.blocks.filter((b) => b.heading).map((b) => b.text.toLowerCase().trim());
182|    for (const { term, kind } of TITLE_TERMS) {
183|      if (heads.includes(term)) return { kind, reason: `heading matches "${term}"` };
184|    }
185|    return null;
186|  };
187|}
