189|// Case- and punctuation-insensitive title compare for contents lists and
190|// duplicate title blocks.
191|function normalizeTitle(text: string): string {
192|  return text
193|    .toLowerCase()
194|    .replace(/[^\p{L}\p{N}\s]/gu, "")
195|    .replace(/\s+/g, " ")
196|    .trim();
197|}
198|
199|// Rule 6: contents tables are mostly short entries plus page numbers, or a
200|// cross-reference list of the book's own chapter titles (pg54 h-0): at
201|// least 3 non-empty blocks, at least half, equal other sections' derived
202|// titles or first headings.
203|export function ruleContentsBody(bookTitle: string, sections: RawSection[]) {
204|  const titles = new Set<string>();
205|  for (const sec of sections) {
206|    titles.add(normalizeTitle(deriveTitle(sec, bookTitle)));
207|    const firstHead = sec.blocks.find((b) => b.heading);
208|    if (firstHead !== undefined) titles.add(normalizeTitle(firstHead.text));
209|  }
210|  titles.delete("");
211|  return (sec: RawSection): { kind: string; reason: string } | null => {
212|    const body = sec.blocks.filter((b) => !b.heading);
213|    if (body.length > 0) {
214|      const shortCount = body.filter((b) => countWords(b.text) < 6).length;
215|      const numbers = body.filter((b) => /^\d+$/.test(b.text.trim())).length;
216|      if (shortCount / body.length >= 0.6 && numbers >= 3) {
217|        return { kind: "contents", reason: "mostly short entries with page numbers" };
218|      }
219|    }
220|    const nonEmpty = sec.blocks.filter((b) => b.text.trim().length > 0);
221|    if (nonEmpty.length === 0) return null;
222|    const mine = new Set([normalizeTitle(deriveTitle(sec, bookTitle))]);
223|    const firstHead = sec.blocks.find((b) => b.heading);
224|    if (firstHead !== undefined) mine.add(normalizeTitle(firstHead.text));
225|    const hits = nonEmpty.filter((b) => {
226|      const text = normalizeTitle(b.text);
227|      return text.length > 0 && titles.has(text) && !mine.has(text);
228|    }).length;
229|    if (hits >= 3 && hits / nonEmpty.length >= 0.5) {
230|      return { kind: "contents", reason: "lists other sections' titles" };
231|    }
232|    return null;
233|  };
